// UserCapabilityOverride One row from either `user_capability_grants` or
// `user_capability_revokes`. `team_id` is null for global
// overrides, set for team-scoped ones. `note` is the
// admin-supplied justification recorded at grant/revoke time.
//
// `expires_at` is the optional time-bound
// expiry. NULL means permanent (the existing default behavior);
// non-null rows get reaped by the background capability
// sweeper once NOW() passes the expiry.
type UserCapabilityOverride struct {
	Capability string `json:"capability"`

	// ExpiresAt Optional auto-expiry timestamp. Null
	// means permanent. Reaped by the background sweeper.
	ExpiresAt *time.Time `json:"expires_at,omitempty"`
	GrantedAt time.Time  `json:"granted_at"`

	// GrantedBy Acting admin's user_ref at time of grant/revoke. Null
	// when the row predates actor recording or was inserted
	// by seed migration.
	GrantedBy *int64 `json:"granted_by,omitempty"`

	// Note Free-text justification — empty when none was supplied.
	Note   *string             `json:"note,omitempty"`
	TeamId *openapi_types.UUID `json:"team_id,omitempty"`
}

// UserCapabilityOverrideRequest Body shared by POST /admin/users/{ref}/grants and POST
// /admin/users/{ref}/revokes. Pass `team_id` to scope the
// override to a team — omit / null for a global override.
//
// `expires_at` is optional. When set, the
// grant or revoke auto-expires at that time and is reaped by
// the background sweeper. Past values are rejected with 400
// (operator must explicitly choose to delete an already-
// expired override rather than land it pre-stale).
type UserCapabilityOverrideRequest struct {
	// Capability Capability code (e.g. `assets.read`, `users.write`).
	Capability string `json:"capability"`

	// ExpiresAt Optional auto-expiry. NULL / omitted =
	// permanent. Past values rejected with 400.
	ExpiresAt *time.Time `json:"expires_at,omitempty"`

	// Note Optional admin-supplied justification recorded with the row.
	Note   *string             `json:"note,omitempty"`
	TeamId *openapi_types.UUID `json:"team_id,omitempty"`
}

// UserCapabilityOverrides Per-user explicit GRANT + REVOKE override lists. Role-derived
// capabilities are NOT included — admins manage those through
// the role editor; this surface only exposes the additive /
// subtractive deltas attached directly to the user.
type UserCapabilityOverrides struct {
	Grants  []UserCapabilityOverride `json:"grants"`
	Revokes []UserCapabilityOverride `json:"revokes"`
}

// UserKeyRotationResult Response from the rotation endpoints
// (/account/security/rotate-federation-keys and
// /admin/federation/users/{ref}/rotate-keys). The new public
// key is base64-encoded for transport; clients render it as
// a verification fingerprint or pass it along to the
// federation actor profile.
type UserKeyRotationResult struct {
	// Algorithm Always `naclbox-x25519-v1` today; recorded for forward-compat.
	Algorithm string `json:"algorithm"`

	// NewPublicKeyB64 Base64-encoded 32-byte X25519 public key for the new version.
	NewPublicKeyB64 string `json:"new_public_key_b64"`

	// NewVersion Version of the freshly-minted current key. Equals previous_version + 1, or 1 if no prior key existed.
	NewVersion int32 `json:"new_version"`

	// PreviousVersion Version of the key just demoted to retained state. 0
	// when no prior current key existed (defensive — shouldn't
	// happen post-I-b but documented for completeness).
	PreviousVersion *int32 `json:"previous_version,omitempty"`

	// RetainedUntilDays Grace window applied to the demoted previous key. Read
	// from sysconfig at rotation time; pass-through so the UI
	// can render "your previous key is reapable on YYYY-MM-DD."
	RetainedUntilDays *int32 `json:"retained_until_days,omitempty"`

	// UserRef Subject user whose key was rotated.
	UserRef int64 `json:"user_ref"`
}

// UserMissingKeypair Drill-down row for the "users missing
// keypair" tile on the admin federation health dashboard.
type UserMissingKeypair struct {
	// Created When the user record was created. Old creation date + no keypair = the I-b boot backfill missed them across reboots.
	Created  *time.Time `json:"created,omitempty"`
	Ref      int64      `json:"ref"`
	Username *string    `json:"username"`
}

// UserPreferencesRequest PATCH-time payload for the per-user preferences row. Wire
// contract is full-object replacement; field-level merge is
// NOT supported. Both fields are optional — an absent
// `notification_channels` clears the user's overrides, an
// absent `default_views` clears the view selections.
type UserPreferencesRequest struct {
	// DefaultViews Default-view selections. Unset fields fall back
	// to per-route defaults at render time. Adding a new view knob
	// is a string-additive change; the valid value sets grow as new
	// layouts ship in later phases.
	DefaultViews *UserPreferencesViews `json:"default_views,omitempty"`

	// EmailCadence Map from event-type key to email delivery cadence
	// (`immediate` | `hourly` | `daily` | `weekly`). Absent key =
	// immediate (send-now). "off" is not a cadence value — mute
	// email by dropping `email` from `notification_channels`.
	// Unknown event types or cadence values trigger a 400.
	EmailCadence *map[string]string `json:"email_cadence,omitempty"`

	// NotificationChannels Map from event-type key to channel list. Unknown event
	// types or unknown channel names trigger a 400. An empty
	// array MEANS "deliver nothing for this event" and
	// overrides the system default; an absent key means
	// "use system default."
	NotificationChannels *map[string][]string `json:"notification_channels,omitempty"`
}

// UserPreferencesResponse GET / PATCH response for per-user preferences.
// Includes the build's known event-type + channel catalogs so
// the UI renders toggle grids without hard-coding the lists
// client-side. Per-event system defaults are surfaced so the UI
// can show "follows system default — in_app only" hints
// alongside each toggle.
type UserPreferencesResponse struct {
	// DefaultChannelsByEvent Per-event-type system default channel list. Applied at
	// notification-write time when the user's
	// `notification_channels` doesn't have that key.
	DefaultChannelsByEvent map[string][]string `json:"default_channels_by_event"`

	// DefaultViews Default-view selections. Unset fields fall back
	// to per-route defaults at render time. Adding a new view knob
	// is a string-additive change; the valid value sets grow as new
	// layouts ship in later phases.
	DefaultViews UserPreferencesViews `json:"default_views"`

	// EmailCadence Per-event-type email cadence. Absent key =
	// immediate. Values: immediate | hourly | daily | weekly.
	EmailCadence *map[string]string `json:"email_cadence,omitempty"`

	// KnownChannels Canonical channel names this build supports
	// (`in_app`, `email`, future: `sms`, `push`, `webhook`).
	KnownChannels []string `json:"known_channels"`

	// KnownEventTypes Canonical ordered list of notification event types this
	// build knows about. Order is the recommended rendering
	// order in the UI.
	KnownEventTypes      []string            `json:"known_event_types"`
	NotificationChannels map[string][]string `json:"notification_channels"`
}

// UserPreferencesViews Default-view selections. Unset fields fall back
// to per-route defaults at render time. Adding a new view knob
// is a string-additive change; the valid value sets grow as new
// layouts ship in later phases.
type UserPreferencesViews struct {
	// BrowseLayout Default browse-feed layout. Valid values today: `grid`,
	// `masonry`, `thumbnail`, `list`. Empty/unset falls back to
	// the route's default.
	BrowseLayout *string `json:"browse_layout,omitempty"`

	// BrowseSort Default browse-feed sort. Valid values today: `newest`,
	// `oldest`, `popular`, `trending`. Empty/unset falls back
	// to the route's default.
	BrowseSort *string `json:"browse_sort,omitempty"`

	// HomeTab Which tab the home page lands on. Valid values today:
	// `following`, `latest`, `trending`, `for_you`. Empty/unset
	// falls back to `latest`.
	HomeTab *string `json:"home_tab,omitempty"`
}

// UserProfileUpdate PATCH semantics — only present fields are updated, but the
// schema treats each field as the new full value (no JSON
// Merge Patch nested ops). Clearing a field is sending an
// empty string (for text) or null (for nullable URLs).
type UserProfileUpdate struct {
	AvatarUrl   *string `json:"avatar_url,omitempty"`
	Bio         *string `json:"bio,omitempty"`
	DisplayName *string `json:"display_name,omitempty"`

	// HideFromAnonymous Owner opt-out from anonymous profile exposure (ADR 0070 →
	// ADR 0024). Default false. When true, the owner's public
	// profile page (/users/by-username, /users/by-ref) returns 404
	// to anonymous viewers even with public mode on. Authenticated
	// viewers and the content-visibility gating are unaffected.
	HideFromAnonymous *bool `json:"hide_from_anonymous,omitempty"`

	// Language BCP47 tag, or empty string to reset to "system default".
	// Validated only loosely server-side — frontend constrains
	// the picker to a known list.
	Language    *string            `json:"language,omitempty"`
	Location    *string            `json:"location,omitempty"`
	SocialLinks *map[string]string `json:"social_links,omitempty"`

	// Theme Empty string resets the pref to "follow system".
	Theme      *UserProfileUpdateTheme `json:"theme,omitempty"`
	WebsiteUrl *string                 `json:"website_url,omitempty"`
}

// UserProfileUpdateTheme Empty string resets the pref to "follow system".
type UserProfileUpdateTheme string

